"""Reconcile observed producer records into v2 manifests; no invented caps."""
import json,pathlib,hashlib,platform,sys
P=pathlib.Path(__file__).resolve().parent;ROOT=P.parents[1];dest=P/'run_manifests';dest.mkdir(exist_ok=True)
for f in sorted((P/'runs').glob('*.json')):
 d=json.loads(f.read_text());outputs=[]
 for q in [f,f.with_suffix('.npz')]:outputs.append(dict(path=str(q.relative_to(ROOT)),sha256=hashlib.sha256(q.read_bytes()).hexdigest(),kind='result'))
 rec=dict(schema_version=2,claim_id='CCT012_'+f.stem,repository=dict(commit=d['revision_before'],dirty=True),command=[sys.executable]+d['argv'],environment=dict(software=[dict(name=k,version=v) for k,v in d['software'].items()],hardware=platform.machine()+' '+platform.system()),mathematics=dict(assertion_tested='Finite conservative wave/tag evolution until declared numerical gate; not physical dwarf closure',coefficient_domain='complex128 and float64',conventions='weighted stretched Cartesian FV, static phase-fitted CN splitting, zero-Dirichlet self gravity once',inputs=['saved incoming assembly or late CCT remnant as pinned'],bounds=d['parameters'],non_claims=['no bound mass or stellar survival inference from stopped runs','no continuum mechanism proof']),randomness=dict(used=bool(d['parameters']['late']),generator='numpy.default_rng PCG64' if d['parameters']['late'] else '',seed=1012 if d['parameters']['late'] else None),run=dict(started_at=d['started_utc'],runtime_seconds=d['seconds'],exit_status=0,status='completed',resource_limits=dict(memory_bytes=None,cpu_seconds=None,max_cores=None,max_threads=None)),outputs=outputs,checks=[dict(name='producer inputs unchanged',passed=d['inputs_before']==d['inputs_after'])],result=d['status'],residual_risks=['soft loop wall budget only; no enforced process memory cap','thread variables request1, not independently enforced','pins sampled after deserialization and before evolution','git revision may change due to concurrent owner commits; source hashes govern','measured peak RSS '+str(d['peak_RSS_bytes'])+' bytes','interpreter path reconstructed from recording environment; producer records argv and version only','revision after '+d['revision_after']],input_artifacts=[dict(path=k,sha256=v,sha256_after=d['inputs_after'][k]) for k,v in d['inputs_before'].items()],declared_results=[x['path'] for x in outputs])
 (dest/(f.stem+'.json')).write_text(json.dumps(rec,indent=2)+'\n')
print('recorded',len(list(dest.glob('*.json'))))
